function Get-WPTProvisioningStatePath { $c=Get-WPTConfig; $root=Join-Path $c.Paths.Data 'State'; if(-not(Test-Path $root)){New-Item $root -ItemType Directory -Force|Out-Null}; Join-Path $root 'provisioning-state.json' }
function Save-WPTProvisioningState { param([Parameter(Mandatory=$true)]$State); $State|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Get-WPTProvisioningStatePath) -Encoding UTF8; $State }
function Get-WPTProvisioningState { $p=Get-WPTProvisioningStatePath; if(-not(Test-Path $p)){return $null}; try{$o=Get-Content -Raw $p|ConvertFrom-Json; if(-not $o.profile -and -not $o.Profile){throw 'Invalid state'}; $o}catch{throw "Invalid provisioning state: $($_.Exception.Message)"} }
function Clear-WPTProvisioningState { $p=Get-WPTProvisioningStatePath; if(Test-Path $p){Remove-Item -LiteralPath $p -Force}; $true }
function Resume-WPTProvisioning { param([string]$Profile='Portfolio',[switch]$Unattended); $s=Get-WPTProvisioningState; if(-not $s){return $null}; $effectiveProfile=if($s.Profile){$s.Profile}else{$Profile}; $plan=@(Get-WPTProvisioningPlan -Profile $effectiveProfile -Unattended:$Unattended); $completed=@($s.Completed); $plan=@($plan|Where-Object{$completed -notcontains $_.Name}); $r=Invoke-WPTProvisioningPlan -Plan $plan -Profile $effectiveProfile -Unattended:$Unattended; if($r.Failure -eq 0){Clear-WPTProvisioningState}; $r }
